/* Geist Mono Medium, SIL Open Font License. Bundled for offline Workers images. */
const FONT =
  "";
export function terminalImageFonts() {
  return [
    {
      name: "Geist Mono",
      data: Uint8Array.from(atob(FONT), (c) => c.charCodeAt(0)).buffer,
      weight: 500 as const,
      style: "normal" as const,
    },
  ];
}
